using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using Xunit;

namespace HgssSave.Tests;

/// <summary>
/// The scene registry is generated by tools/make_scenes.py. These tests keep it a plan that can
/// always be executed: unique ids, a real warp op per scene, existing base presets, and the
/// minimum coverage the tool promises (16 gyms before/after, Elite Four, legendaries, Red, events).
/// </summary>
public sealed class SceneTests
{
    private static string RegistryPath()
    {
        var dir = AppContext.BaseDirectory;
        while (dir is not null && !Directory.Exists(Path.Combine(dir, "registry", "presets")))
            dir = Path.GetDirectoryName(dir);
        return Path.Combine(dir ?? throw new DirectoryNotFoundException("registry"), "registry", "hgss-us.scenes.json");
    }

    private static JsonElement Scenes()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(RegistryPath()));
        Assert.Equal("hgss-save.scenes/v1", doc.RootElement.GetProperty("schema").GetString());
        return doc.RootElement.GetProperty("scenes").Clone();
    }

    private static Dictionary<string, string> PresetGames()
    {
        var path = Path.Combine(Path.GetDirectoryName(RegistryPath())!, "presets", "index.json");
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        return doc.RootElement.GetProperty("presets").EnumerateArray()
            .ToDictionary(p => p.GetProperty("name").GetString()!, p => p.GetProperty("game").GetString()!);
    }

    [Fact]
    public void ScenesHaveUniqueIdsAndExecutableWarps()
    {
        var presets = PresetGames();
        var ids = new HashSet<string>();
        foreach (var scene in Scenes().EnumerateArray())
        {
            var id = scene.GetProperty("id").GetString()!;
            Assert.True(ids.Add(id), $"duplicate scene id {id}");
            var basePreset = scene.GetProperty("base_preset").GetString();
            if (basePreset is not null)
            {
                Assert.Contains(basePreset, presets.Keys);
                Assert.Equal(scene.GetProperty("game").GetString(), presets[basePreset]);
            }

            var expect = scene.GetProperty("expect");
            var map = expect.GetProperty("map").GetInt32();
            var warp = expect.GetProperty("warp").GetInt32();
            var warps = scene.GetProperty("ops").EnumerateArray()
                .Where(o => o.GetProperty("op").GetString() == "location.warp")
                .ToList();
            var last = Assert.Single(warps);
            Assert.Equal(map, last.GetProperty("map").GetInt32());
            Assert.Equal(warp, last.GetProperty("warp").GetInt32());

            foreach (var flags in new[] { "flags_on", "flags_off" })
                Assert.Equal(JsonValueKind.Array, expect.GetProperty(flags).ValueKind);
            if (expect.TryGetProperty("spawn_after", out var after))
            {
                // The map's own init script moves the player on load; the scene still stores the
                // warp tile in x/y, and the boot check asserts this post-load tile instead.
                Assert.Equal(JsonValueKind.Object, after.ValueKind);
                Assert.True(after.GetProperty("x").GetInt32() >= 0);
                Assert.True(after.GetProperty("y").GetInt32() >= 0);
            }
            foreach (var list in new[] { "vars", "items" })
            {
                if (!expect.TryGetProperty(list, out var element))
                    continue;
                Assert.Equal(JsonValueKind.Array, element.ValueKind);
                foreach (var entry in element.EnumerateArray())
                    Assert.False(string.IsNullOrEmpty(entry.GetProperty("name").GetString()));
            }

            Assert.NotEmpty(scene.GetProperty("sources").EnumerateArray());
        }
    }

    [Fact]
    public void MinimumCoverageIsPresent()
    {
        var scenes = Scenes().EnumerateArray().ToList();
        var ids = scenes.Select(s => s.GetProperty("id").GetString()!).ToHashSet();
        for (var gym = 1; gym <= 16; gym++)
        {
            Assert.Contains(scenes, s => s.GetProperty("kind").GetString() == "gym"
                && s.GetProperty("id").GetString()!.StartsWith($"gym-{gym:00}-")
                && s.GetProperty("id").GetString()!.EndsWith("-before"));
            Assert.Contains(scenes, s => s.GetProperty("kind").GetString() == "gym"
                && s.GetProperty("id").GetString()!.StartsWith($"gym-{gym:00}-")
                && s.GetProperty("id").GetString()!.EndsWith("-after"));
        }

        Assert.Contains("e4-before", ids);
        Assert.Contains("e4-after", ids);
        Assert.Contains("legendary-red", ids);
        foreach (var legendary in new[] { "lugia", "ho-oh", "articuno", "zapdos", "moltres", "mewtwo", "suicune", "groudon", "kyogre", "rayquaza" })
            Assert.Contains($"legendary-{legendary}", ids);
        Assert.Contains("event-hall-of-fame", ids);
    }

    [Fact]
    public void GymScenesNameTheLeaderObjectAndHideFlag()
    {
        foreach (var scene in Scenes().EnumerateArray())
        {
            if (scene.GetProperty("kind").GetString() != "gym")
                continue;
            var actor = scene.GetProperty("actor");
            Assert.StartsWith("SPRITE_GSLEADER", actor.GetProperty("sprite").GetString());
            Assert.StartsWith("FLAG_HIDE_", actor.GetProperty("hide_flag").GetString());
            Assert.NotEmpty(actor.GetProperty("script").GetString()!);
        }
    }
}
